import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Bibliography","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/bibliography.md","filePath":"ecosystem/bibliography.md"}`),a={name:`ecosystem/bibliography.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="bibliography" tabindex="-1">Bibliography <a class="header-anchor" href="#bibliography" aria-label="Permalink to “Bibliography”">​</a></h1><p>These academic works are a major inspiration for Handl. There is already a substantial body of mathematical groundwork for arrows via category theory — that is what we are drawing on.</p><p>Foundational work behind the arrow calculus and the categorical semantics the kernel is built on.</p><h2 id="arrows" tabindex="-1">Arrows <a class="header-anchor" href="#arrows" aria-label="Permalink to “Arrows”">​</a></h2><ul><li><strong>John Hughes</strong> — <a href="https://doi.org/10.1016/S0167-6423(99)00023-4" target="_blank" rel="noreferrer"><em>Generalising Monads to Arrows</em></a> (2000, <em>Science of Computer Programming</em>). Introduced arrows and their core combinators (<code>arr</code>, <code>&gt;&gt;&gt;</code>, <code>first</code>).</li><li><strong>Ross Paterson</strong> — <a href="https://doi.org/10.1145/507635.507664" target="_blank" rel="noreferrer"><em>A New Notation for Arrows</em></a> (2001, ICFP). Formalized proc notation, algebraic laws, and categorical correspondences.</li><li><strong>Sam Lindley, Philip Wadler &amp; Jeremy Yallop</strong> — <a href="https://doi.org/10.1017/S095679680999027X" target="_blank" rel="noreferrer"><em>The Arrow Calculus</em></a> (2010, <em>Journal of Functional Programming</em>). Defined a formal typed calculus and equational semantics for arrows.</li></ul><h2 id="categorical-semantics" tabindex="-1">Categorical semantics <a class="header-anchor" href="#categorical-semantics" aria-label="Permalink to “Categorical semantics”">​</a></h2><ul><li><strong>Eugenio Moggi</strong> — <a href="https://doi.org/10.1016/0890-5401(91)90052-4" target="_blank" rel="noreferrer"><em>Notions of Computation and Monads</em></a> (1991, <em>Information and Computation</em>). Monads as notions of computation.</li><li><strong>John Power &amp; Edmund Robinson</strong> — <a href="https://doi.org/10.1017/S0960129597002375" target="_blank" rel="noreferrer"><em>Premonoidal Categories and Notions of Computation</em></a> (1997, <em>Mathematical Structures in Computer Science</em>).</li><li><strong>John Power &amp; Hayo Thielecke</strong> — <a href="https://doi.org/10.1007/3-540-48523-6_59" target="_blank" rel="noreferrer"><em>Closed Freyd- and κ-categories</em></a> (1999, ICALP). Freyd and premonoidal categories — the canonical categorical model separating pure values from effectful computations.</li><li><strong>Paul Levy</strong> — <em>Call-by-push-value: A Subsuming Paradigm</em> (PhD thesis, University of Birmingham, 2003/2004). Value/computation discipline that premonoidal models are built on.</li></ul><h2 id="monads-in-prof" tabindex="-1">Monads in Prof <a class="header-anchor" href="#monads-in-prof" aria-label="Permalink to “Monads in Prof”">​</a></h2><ul><li><strong>Chris Heunen &amp; Bart Jacobs</strong> — <a href="https://doi.org/10.1016/j.entcs.2006.04.012" target="_blank" rel="noreferrer"><em>Arrows, like Monads, are Monoids</em></a> (2006, ENTCS). Arrows as monoids in categories of bifunctors.</li><li><strong>Bart Jacobs, Chris Heunen &amp; Ichiro Hasuo</strong> — <a href="https://doi.org/10.1017/S0956796809007308" target="_blank" rel="noreferrer"><em>Categorical Semantics for Arrows</em></a> (2009, <em>Journal of Functional Programming</em>). Denotational semantics via Eilenberg–Moore and Kleisli constructions — &quot;arrows are Freyd categories.&quot;</li><li><strong>Kazuyuki Asada</strong> — <a href="https://doi.org/10.1145/1863597.1863607" target="_blank" rel="noreferrer"><em>Arrows are Strong Monads</em></a> (2010, <a href="https://www.riec.tohoku.ac.jp/~asada/papers/arrStrMnd.pdf" target="_blank" rel="noreferrer">PDF</a>). Identifies <code>first</code> with strength: arrows are strong monads (promonads) in <code>Prof</code>.</li></ul><h2 id="effects-and-handlers-for-arrows" tabindex="-1">Effects and handlers for arrows <a class="header-anchor" href="#effects-and-handlers-for-arrows" aria-label="Permalink to “Effects and handlers for arrows”">​</a></h2><ul><li><strong>Takahiro Sanada</strong> — <a href="https://doi.org/10.1017/S0956796824000066" target="_blank" rel="noreferrer"><em>Algebraic Effects and Handlers for Arrows</em></a> (2024, <em>Journal of Functional Programming</em>; also <a href="https://icfp24.sigplan.org/details/icfp-2024-jfp-first-papers/1/Algebraic-effects-and-handlers-for-arrows" target="_blank" rel="noreferrer">ICFP 2024</a>). Extended the arrow calculus with algebraic effects and handlers via algebras over strong promonads.</li><li><strong>Takahiro Sanada, Keisuke Hoshino, Kenshin Hirai &amp; Shin-ya Katsumata</strong> — <a href="https://doi.org/10.1145/3828704" target="_blank" rel="noreferrer"><em>Programming Backpropagation with Reverse Handlers for Arrows</em></a> (2026, PACMPL ICFP; also <a href="https://arxiv.org/abs/2602.18090" target="_blank" rel="noreferrer">arXiv:2602.18090</a>). Modeled neural networks and backpropagation via linear reverse effect handlers, combining strong promonads with Cartesian reverse differential categories.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};